#!/bin/bash
# Builds the caddy package into out/: the binary from main.go and go.mod with the flags of
# Caddy's own release build (.goreleaser.yml v2.11.7, lines 33-89), man pages and bash
# completion generated by that binary as Caddy does it (lines 26-31), and Caddy's
# packaging files from caddyserver/dist at DIST_REF. Fails unless every plugin of main.go
# is in the binary. Needs go, git, gzip and nfpm on PATH; runs on linux/amd64.
#
# Environment: DIST_REF (commit of caddyserver/dist, required), PKG_RELEASE (package
# revision, default 0).
set -euo pipefail

cd "$(dirname "$0")/.."
. scripts/plugins.sh

: "${DIST_REF:?set DIST_REF to a commit of caddyserver/dist}"
PKG_RELEASE="${PKG_RELEASE:-0}"

rm -rf build out
mkdir -p build/man out

CADDY_VERSION="$(go list -m -f '{{.Version}}' github.com/caddyserver/caddy/v2)"
CADDY_VERSION="${CADDY_VERSION#v}"
# one process instead of "sed | head": under pipefail, head closing the pipe early can make
# sed die of SIGPIPE and the whole assignment fail
PACKAGING_VERSION="$(awk -F'[][]' '/^## \[[0-9]/ { print $2; exit }' CHANGELOG.md)"
PLUGINS="$(plugin_imports main.go | paste -sd ' ' -)"
export CADDY_VERSION PKG_RELEASE PACKAGING_VERSION PLUGINS

echo "== caddy $CADDY_VERSION, package revision $PKG_RELEASE, packaging $PACKAGING_VERSION"
echo "== plugins: $PLUGINS"

CGO_ENABLED=0 GOOS=linux GOARCH=amd64 go build \
    -trimpath -mod=readonly -ldflags '-s -w' -tags nobadger,nomysql,nopgx \
    -o build/caddy .

build/caddy version
check_plugins build/caddy main.go

build/caddy manpage --directory build/man
gzip -9n build/man/*
build/caddy completion bash > build/bash-completion

git clone --quiet https://github.com/caddyserver/dist build/dist
git -C build/dist checkout --quiet "$DIST_REF"

nfpm package --config nfpm.yaml --packager deb --target out/
printf '%s-%s\n' "$CADDY_VERSION" "$PKG_RELEASE" > out/version.txt

ls -l out/
dpkg-deb --info out/*.deb
dpkg-deb --contents out/*.deb
